const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};
const auth = headers['authorization'] || headers['Authorization'] || '';
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
if (!token) return { json: { ok: false, status: 401, error: 'Missing session token' } };
// 'pull' is the default and NEVER returns the raw stream key. Revealing the key
// is a separate, explicit action so it cannot happen as a side effect of
// opening the Go Live modal.
const action = String(body.action || 'pull').toLowerCase().trim();
if (action !== 'pull' && action !== 'reveal_key') {
  return { json: { ok: false, status: 400, error: "action must be 'pull' or 'reveal_key'" } };
}
return { json: { token: token, action: action } };

const rows = $input.item.json;
const row = Array.isArray(rows) ? (rows[0] || null) : (rows && (rows.user_id || rows.id) ? rows : null);
if (!row) return { json: { ok: false, status: 401, error: 'Invalid or expired session' } };
if (row.user_role !== 'admin') return { json: { ok: false, status: 403, error: 'Admin access required' } };
return { json: { ok: true, action: $('Extract').first().json.action } };

// Every upstream fetch uses fullResponse, so each arrives as ONE item shaped
// { body, statusCode, headers } instead of n8n splitting an array body into
// many items. Reference with .first() -- .item depends on paired-item lineage,
// which HTTP nodes break.
function res(name){
  try { const j = $(name).first().json || {}; return { code: j.statusCode || 0, body: j.body }; }
  catch (e) { return { code: 0, body: null }; }
}
function arr(v){ return Array.isArray(v) ? v : []; }

const action = $('Check Admin').first().json.action || 'pull';
const ch = res('Fetch Channels');
const pl = res('Fetch Platforms');
const sk = res('Fetch Stream Key');
const sv = res('Fetch Servers');
const rq = res('Fetch Requirements');

if (ch.code === 401 || ch.code === 403 || sk.code === 401 || sk.code === 403) {
  return { json: { ok: false, status: 401,
    error: 'Restream authorization failed or expired. Re-authorize the "Restream OAuth2" credential in n8n (Credentials -> Restream OAuth2 -> Connect).' } };
}
if (ch.code && (ch.code < 200 || ch.code >= 300)) {
  return { json: { ok: false, status: 502, error: 'Restream API error on channels (HTTP ' + ch.code + ').' } };
}

// ---- the stream key: masked by default, raw only on explicit request -------
// It is never logged and never written to a database column. On 'pull' the
// caller learns only that a key exists and its last four characters.
const skBody = sk.body || {};
const rawKey = String(skBody.streamKey || skBody.stream_key || '');
const keyMasked = rawKey ? ('****' + rawKey.slice(-4)) : '';

if (action === 'reveal_key') {
  if (!rawKey) {
    return { json: { ok: false, status: 404, error: 'Restream did not return a stream key for this account.' } };
  }
  return { json: { ok: true, status: 200, reveal: true, stream_key: rawKey } };
}

// ---- platform mapping ------------------------------------------------------
const NAME_TO_KEY = {
  'tiktok': 'tiktok', 'youtube': 'youtube', 'youtube stream now': 'youtube',
  'facebook': 'facebook', 'facebook pages': 'facebook',
  'instagram': 'instagram', 'twitter': 'x', 'x': 'x'
};
const ALL_KEYS = ['tiktok','youtube','facebook','instagram','x'];

const idToName = {};
arr(pl.body).forEach(function(p){ if (p && p.id != null) idToName[String(p.id)] = String(p.name || ''); });

// Requirements come back as { platform_key: [ {code,label,help_url,satisfied,blocking}, ... ] }
let reqs = {};
if (rq.body && typeof rq.body === 'object' && !Array.isArray(rq.body)) reqs = rq.body;
const reqsUnavailable = (rq.code && (rq.code < 200 || rq.code >= 300));

// ---- readiness -------------------------------------------------------------
// Restream's active flag means "linked", NOT "able to broadcast". A linked
// TikTok account still cannot go LIVE below the follower threshold; YouTube
// needs 24h after first activation; Instagram rejects third-party RTMP for
// most accounts. Reporting those as READY is how a show goes dark on two
// destinations without anyone noticing, so unmet blocking requirements
// downgrade to ACTION_REQUIRED.
const byKey = {};
arr(ch.body).forEach(function(c){
  if (!c || c.id == null) return;
  const pname = idToName[String(c.streamingPlatformId)] || '';
  const key = NAME_TO_KEY[pname.toLowerCase()] || null;
  if (!key) return;
  const url = String(c.url || '').trim();
  const active = c.active !== false;
  // Keep the strongest signal if an account has several channels per platform.
  if (!byKey[key] || (active && !byKey[key].active)) {
    byKey[key] = { platform_key: key, platform_name: pname, display_name: String(c.displayName || ''),
                   url: url, embed_url: String(c.embedUrl || ''), active: active };
  }
});

const platforms = ALL_KEYS.map(function(key){
  const c = byKey[key] || null;
  const list = arr(reqs[key]);
  const blockers = list.filter(function(r){ return r && r.blocking && !r.satisfied; });

  let state, detail;
  if (reqsUnavailable) {
    state = 'ERROR';
    detail = 'Could not read platform requirements.';
  } else if (!c) {
    state = 'UNAVAILABLE';
    detail = 'Not connected in Restream.';
  } else if (!c.active) {
    state = 'UNAVAILABLE';
    detail = 'Connected but disabled in Restream.';
  } else if (blockers.length) {
    state = 'ACTION_REQUIRED';
    detail = blockers[0].label;
  } else if (!c.url) {
    state = 'CONNECTED';
    detail = 'Linked, but Restream reports no public watch URL yet.';
  } else {
    state = 'READY';
    detail = 'Connected and eligible to broadcast.';
  }

  return {
    platform_key: key,
    platform_name: c ? c.platform_name : key,
    display_name: c ? c.display_name : '',
    connected: !!c,
    active: c ? c.active : false,
    url: c ? c.url : '',
    state: state,
    detail: detail,
    blocking_requirements: blockers.map(function(r){
      return { code: r.code, label: r.label, help_url: r.help_url || '' };
    })
  };
});

// Only offer watch links for destinations that can actually carry the show.
const watch_urls = {};
platforms.forEach(function(p){ if (p.state === 'READY' && p.url) watch_urls[p.platform_key] = p.url; });

const servers = arr(sv.body);
let ingest = '';
for (let i = 0; i < servers.length; i++) {
  if (String(servers[i].name || '').toLowerCase() === 'autodetect') { ingest = String(servers[i].rtmpUrl || ''); break; }
}
if (!ingest && servers.length) ingest = String(servers[0].rtmpUrl || '');

return { json: {
  ok: true,
  status: 200,
  platforms: platforms,
  watch_urls: watch_urls,
  ready_count: platforms.filter(function(p){ return p.state === 'READY'; }).length,
  rtmp_ingest_url: ingest,
  rtmp_connected: !!ingest,
  stream_key_available: !!rawKey,
  stream_key_masked: keyMasked,
  channels_found: arr(ch.body).length
} };
